var e=[{key:`extensor-digitorum-longus`,identities:[[`FMA22548`,`right`,`FJ1406`],[`FMA22549`,`left`,`FJ1406M`]],scope:`Reference muscle surface only; no pathological tendon, nerve territory, compartment pressure or patient-specific lesion is represented.`,pathology:{body:`Weakness of the long toe extensors can accompany anterior-compartment muscle injury or dysfunction of their deep fibular motor supply.`,bullets:[`Difficulty straightening toes 2–5 is not sufficient to distinguish a tendon lesion from neurological weakness.`]},clinical:{body:`Compare lesser-toe extension with ankle dorsiflexion and the wider motor/sensory pattern.`,bullets:[`A muscle-belly selection does not isolate its individual distal tendon slips.`]},references:[`https://www.ncbi.nlm.nih.gov/books/NBK539725/`,`https://www.ncbi.nlm.nih.gov/books/NBK554393/`]},{key:`extensor-hallucis-longus`,identities:[[`FMA22546`,`right`,`FJ1408`],[`FMA22547`,`left`,`FJ1408M`]],scope:`Reference muscle surface only; no pathological tendon, nerve territory, compartment pressure or patient-specific lesion is represented.`,pathology:{body:`Impaired great-toe extension may reflect local muscle/tendon injury or a neurological lesion.`,bullets:[`Great-toe weakness alone does not prove an L5 root lesion.`]},clinical:{body:`Assess hallux extension alongside other dorsiflexors and the neurological examination.`,bullets:[`The long extensor reaches the distal phalanx; short hallux-extensor action is not an equivalent substitute.`]},references:[`https://www.ncbi.nlm.nih.gov/books/NBK539725/`,`https://www.ncbi.nlm.nih.gov/books/NBK554393/`]},{key:`fibularis-brevis`,identities:[[`FMA22554`,`right`,`FJ1409`],[`FMA22555`,`left`,`FJ1409M`]],scope:`Reference muscle surface only; no pathological tendon, nerve territory, compartment pressure or patient-specific lesion is represented.`,pathology:{body:`Fibularis brevis can develop tendinopathy, longitudinal tendon splitting or displacement around the lateral ankle.`,bullets:[`Lateral ankle pain is not always a ligament sprain; tendon and ligament injuries can coexist.`]},clinical:{body:`Localise symptoms along the retromalleolar tendon and towards its fifth-metatarsal attachment.`,bullets:[`Distinguish painful eversion from superficial-fibular motor weakness.`,`A static reference surface cannot demonstrate dynamic tendon subluxation.`]},references:[`https://www.ncbi.nlm.nih.gov/books/NBK544354/`,`https://www.ncbi.nlm.nih.gov/books/NBK519526/`]},{key:`fibularis-longus`,identities:[[`FMA22552`,`right`,`FJ1410`],[`FMA22553`,`left`,`FJ1410M`]],scope:`Reference muscle surface only; no pathological tendon, nerve territory, compartment pressure or patient-specific lesion is represented.`,pathology:{body:`Fibularis longus tendon disease can cause lateral ankle or plantar-lateral foot pain.`,bullets:[`Its plantar course around the cuboid differs from the brevis tendon ending at the fifth-metatarsal base.`]},clinical:{body:`Relate eversion and first-ray support to the longus tendon course.`,bullets:[`If an os peroneum is present within the tendon, its associated pathology requires separate assessment; this atlas selection does not establish that variant.`,`Do not infer tendon integrity from preserved muscle-belly geometry.`]},references:[`https://www.ncbi.nlm.nih.gov/books/NBK544354/`,`https://www.ncbi.nlm.nih.gov/books/NBK519526/`]},{key:`fibularis-tertius`,identities:[[`FMA22550`,`right`,`FJ1411`],[`FMA22551`,`left`,`FJ1411M`]],scope:`Reference muscle surface only; no pathological tendon, nerve territory, compartment pressure or patient-specific lesion is represented.`,pathology:{body:`Tertius can share weakness with other anterior-compartment muscles in deep fibular nerve dysfunction.`,bullets:[`Its normal presence and separation from extensor digitorum longus vary; anatomical absence is not an acquired tear.`]},clinical:{body:`Despite its fibularis name, tertius belongs to the anterior compartment and assists dorsiflexion as well as eversion.`,bullets:[`It should not be assigned the superficial fibular supply of longus and brevis.`]},references:[`https://www.ncbi.nlm.nih.gov/books/NBK539725/`]},{key:`flexor-digitorum-longus`,identities:[[`FMA65016`,`right`,`FJ1414`],[`FMA65017`,`left`,`FJ1414M`]],scope:`Reference muscle surface only; no pathological tendon, nerve territory, compartment pressure or patient-specific lesion is represented.`,pathology:{body:`Long toe-flexor injury or tibial motor dysfunction can alter active lesser-toe flexion.`,bullets:[`A curled toe does not by itself identify a torn or overactive FDL; joint position and other muscles also matter.`]},clinical:{body:`Relate FDL to distal-joint flexion of toes 2–5, while recognising the combined action of long and intrinsic flexors.`,bullets:[`This grouped tendon course cannot establish the integrity of one digital slip or diagnose a specific motor lesion.`]},references:[`https://www.ncbi.nlm.nih.gov/books/NBK537340/`]},{key:`flexor-hallucis-longus`,identities:[[`FMA65014`,`right`,`FJ1415`],[`FMA65015`,`left`,`FJ1415M`]],scope:`Reference muscle surface only; no pathological tendon, nerve territory, compartment pressure or patient-specific lesion is represented.`,pathology:{body:`FHL can develop tendon-sheath inflammation and tendon tears in dancers and nondancers.`,bullets:[`Repeated pointe work can be associated with symptoms, but FHL disease is not confined to ballet.`]},clinical:{body:`Posteromedial ankle symptoms with hallux movement may prompt assessment of the FHL tendon and its sheath.`,bullets:[`Correlate imaging with the clinical findings; the cited surgical series does not establish prevalence, a diagnostic rule or a recovery timetable.`,`Long hallux flexion acts at the distal phalanx, unlike the short flexor insertion.`]},references:[`https://pubmed.ncbi.nlm.nih.gov/9677077/`,`https://pubmed.ncbi.nlm.nih.gov/8816655/`,`https://www.ncbi.nlm.nih.gov/books/NBK537340/`]},{key:`plantaris`,identities:[[`FMA22560`,`right`,`FJ1429`],[`FMA22561`,`left`,`FJ1429M`]],scope:`Reference muscle surface only; no pathological tendon, nerve territory, compartment pressure or patient-specific lesion is represented.`,pathology:{body:`Plantaris injury is possible, but the label tennis leg should not automatically be equated with plantaris rupture.`,bullets:[`A clinical ultrasound study found medial gastrocnemius injury much more often than plantaris rupture.`]},clinical:{body:`Acute calf pain requires consideration of other muscle injuries and non-muscular causes, including deep-vein thrombosis.`,bullets:[`The long thin plantaris tendon is not a nerve; absence or variable insertion can be normal.`,`Neither selecting nor exploding this reference muscle excludes thrombosis.`]},references:[`https://pubmed.ncbi.nlm.nih.gov/12091669/`,`https://www.ncbi.nlm.nih.gov/books/NBK459362/`]},{key:`popliteus`,identities:[[`FMA22591`,`right`,`FJ1430`],[`FMA22592`,`left`,`FJ1430M`]],scope:`Reference muscle surface only; no pathological tendon, nerve territory, compartment pressure or patient-specific lesion is represented.`,pathology:{body:`Popliteus injury may occur alone or as part of a wider posterolateral knee injury.`,bullets:[`Pain at the back or outer side of the knee is not a stand-alone popliteus diagnosis.`]},clinical:{body:`Relate symptoms to knee rotation and the wider ligament, meniscal and stability assessment.`,bullets:[`The muscle does not cross the ankle.`,`The isolated-injury literature is limited; athlete case reports and series do not supply a universal treatment or return-to-sport rule.`]},references:[`https://pubmed.ncbi.nlm.nih.gov/35252463/`,`https://www.ncbi.nlm.nih.gov/books/NBK526084/`]},{key:`soleus`,identities:[[`FMA22558`,`right`,`FJ1437`],[`FMA22559`,`left`,`FJ1437M`]],scope:`Reference muscle surface only; no pathological tendon, nerve territory, compartment pressure or patient-specific lesion is represented.`,pathology:{body:`Soleus strain and injury to the shared Achilles apparatus can both affect calf loading, but they are not the same lesion.`,bullets:[`A deep calf muscle lesion can be difficult to localise from pain alone.`]},clinical:{body:`Soleus crosses the ankle, not the knee; bending the knee changes gastrocnemius length without turning movement into a perfectly isolated soleus test.`,bullets:[`Acute severe or escalating calf pain after injury, particularly with tense swelling or neurological change, warrants emergency assessment for possible compartment syndrome.`,`Explode mode does not model pressure or perform a decompression.`]},references:[`https://www.ncbi.nlm.nih.gov/books/NBK537340/`,`https://pubmed.ncbi.nlm.nih.gov/12091669/`,`https://www.orthoinfo.org/diseases--conditions/compartment-syndrome/`]},{key:`tibialis-anterior`,identities:[[`FMA22544`,`right`,`FJ1439`],[`FMA22545`,`left`,`FJ1439M`]],scope:`Reference muscle surface only; no pathological tendon, nerve territory, compartment pressure or patient-specific lesion is represented.`,pathology:{body:`Tibialis-anterior tendon disease or rupture can impair dorsiflexion. Foot drop can also arise from nerve, root or other neurological disease.`,bullets:[`A foot-drop pattern is not synonymous with a torn tibialis-anterior tendon.`]},clinical:{body:`Assess ankle dorsiflexion and inversion alongside toe extension, sensation and gait.`,bullets:[`Differentiate local tendon failure from a broader neurological pattern; a single movement cannot localise the lesion.`,`Acute compartment syndrome threatens muscle and nerve perfusion and needs emergency assessment, unlike a routine exertional ache.`]},references:[`https://www.ncbi.nlm.nih.gov/books/NBK513304/`,`https://www.ncbi.nlm.nih.gov/books/NBK554393/`,`https://www.orthoinfo.org/diseases--conditions/compartment-syndrome/`]},{key:`tibialis-posterior`,identities:[[`FMA65018`,`right`,`FJ1440`],[`FMA65019`,`left`,`FJ1440M`]],scope:`Reference muscle surface only; no pathological tendon, nerve territory, compartment pressure or patient-specific lesion is represented.`,pathology:{body:`Posterior tibial tendon dysfunction can contribute to progressive collapsing foot deformity.`,bullets:[`Arch collapse is a multi-structure problem involving ligaments and alignment, not simply one damaged muscle.`]},clinical:{body:`Medial ankle/arch symptoms, standing alignment and heel-rise function help assess the posterior tibial apparatus.`,bullets:[`Pain-limited performance is not proof of tendon rupture.`,`This source does not show spring-ligament failure, weight-bearing collapse or a validated deformity stage.`]},references:[`https://www.orthoinfo.org/diseases--conditions/posterior-tibial-tendon-dysfunction`,`https://www.ncbi.nlm.nih.gov/books/NBK539913/`]},{key:`gastrocnemius`,identities:[[`FMA45957`,`right`,`FJ1397`],[`FMA45958`,`left`,`FJ1397M`],[`FMA45960`,`right`,`FJ1394`],[`FMA45961`,`left`,`FJ1394M`]],scope:`Whole-apparatus clinical context applies to both source heads; no diseased surface, subtendon or patient-specific lesion is segmented.`,pathology:{body:`Gastrocnemius strains and Achilles tendon ruptures are distinct injuries. Medial gastrocnemius injury is a common explanation for the clinical label tennis leg.`,bullets:[`Calf pain can also involve soleus, plantaris or deep-vein thrombosis; location alone is insufficient.`]},clinical:{body:`Gastrocnemius crosses knee and ankle, whereas soleus does not. Both transmit force through the shared Achilles apparatus.`,bullets:[`Sudden posterior ankle pain with loss of push-off warrants prompt assessment for Achilles injury.`,`The selected head is not a separate Achilles subtendon, simulated tear or calf-squeeze examination.`]},references:[`https://pubmed.ncbi.nlm.nih.gov/12091669/`,`https://www.orthoinfo.org/diseases--conditions/achilles-tendon-rupture-tear/`,`https://www.ncbi.nlm.nih.gov/books/NBK459362/`]}],t=new Map(e.flatMap(e=>e.identities.map(t=>[t[0],{group:e,identity:t}])));function n(e,n){if(n!==`pathology`&&n!==`clinical`||e.system!==`muscles`||e.category!==`muscle`||e.region!==`leg`||e.regions.length!==1||e.regions[0]!==`leg`||e.sourceTree!==`isa`)return;let r=t.get(e.fmaId);if(!r||e.laterality!==r.identity[1]||e.sources.length!==1||e.sources[0].file!==r.identity[2])return;let{group:i}=r,a=i[n];return{readiness:`draft`,title:`${e.name} · ${n===`pathology`?`Injury & disease`:`Clinical context`} · draft`,body:a.body,bullets:[...a.bullets,i.scope],note:[`Draft teaching; independent anatomical and clinical review pending. Educational context, not a patient diagnosis or treatment plan.`,e.coverageNote].filter(Boolean).join(` `),citations:[...i.references]}}var r=`https://www.ncbi.nlm.nih.gov/books/NBK539705/`,i=`https://www.ncbi.nlm.nih.gov/books/NBK513273/`,a=`https://anatomy.ttuhscep.edu/anatomytables/muscles_lowerlimb.html`,o=`https://www.orthoinfo.org/diseases--conditions/hammer-toe`,s=`https://www.orthoinfo.org/diseases--conditions/bunions/`,c=`Reference muscle surface only; no nerve territory, pathological tendon, deformity or patient-specific lesion is segmented.`,l=[{key:`first-lumbrical`,identities:[[`FMA37717`,`right`,`FJ1383`],[`FMA37718`,`left`,`FJ1383M`]],scope:c,pathology:{body:`Intrinsic muscle weakness can contribute to lesser-toe imbalance. A deformed second toe does not establish an isolated first-lumbrical injury.`,bullets:[`Joint stiffness, tendon balance and neurological findings need to be considered together.`]},clinical:{body:`The first foot lumbrical uses the medial plantar motor supply, unlike the other three lumbricals.`,bullets:[`Relate its action to flexion at the second-toe base and extension at the interphalangeal joints; this is not a perfectly isolated bedside test.`]},references:[r,o]},{key:`lateral-lumbricals`,identities:[[`FMA37719`,`right`,`FJ1385`],[`FMA37720`,`left`,`FJ1385M`],[`FMA37485`,`right`,`FJ1387`],[`FMA37486`,`left`,`FJ1387M`],[`FMA37483`,`right`,`FJ1389`],[`FMA37484`,`left`,`FJ1389M`]],scope:`Shared clinical context for lumbricals 2–4; each source muscle remains individually selectable. No denervation or deformity is rendered.`,pathology:{body:`Weakness affecting the lateral plantar motor supply can impair these lumbricals and other intrinsic muscles together.`,bullets:[`A bent toe is not proof of a single lumbrical tear or one nerve-compression site.`]},clinical:{body:`Lumbricals 2–4 act on toes 3–5 and receive lateral plantar innervation; do not apply the median/ulnar pattern of hand lumbricals.`,bullets:[`Compare toe posture, active movement, passive correction and sensation as parts of a wider examination.`]},references:[r,i,o]},{key:`plantar-interossei`,identities:[[`FMA37745`,`right`,`FJ1384`],[`FMA37746`,`left`,`FJ1384M`],[`FMA37743`,`right`,`FJ1386`],[`FMA37744`,`left`,`FJ1386M`],[`FMA37741`,`right`,`FJ1388`],[`FMA37742`,`left`,`FJ1388M`]],scope:`Shared clinical context for three separately identified plantar interossei; absent dorsal interossei are not supplied by these selections.`,pathology:{body:`Interosseous weakness can accompany lateral plantar nerve dysfunction and altered intrinsic balance.`,bullets:[`Toe malalignment alone cannot distinguish muscle weakness from tendon or joint disease.`]},clinical:{body:`Assess movement towards the second-toe axis: plantar interossei adduct toes 3–5, not towards a hand-like middle-finger axis.`,bullets:[`They also act at metatarsophalangeal and interphalangeal joints; reduced movement is not a selective nerve test.`]},references:[a,i,o]},{key:`abductor-digiti-minimi`,identities:[[`FMA37463`,`right`,`FJ1390`],[`FMA37464`,`left`,`FJ1390M`]],scope:c,pathology:{body:`The nerve supplying this muscle is relevant to the proposed Baxter neuropathy explanation for plantar heel pain.`,bullets:[`Fatty infiltration of the muscle on MRI is not an established stand-alone diagnosis of Baxter neuropathy: a 2025 systematic review found the association uncertain.`]},clinical:{body:`Correlate heel symptoms with the wider examination and actual imaging; the reference mesh cannot demonstrate denervation.`,bullets:[`Do not infer a symptomatic compressed nerve, or an indication for surgery, from muscle appearance alone.`]},references:[`https://pubmed.ncbi.nlm.nih.gov/12197005/`,`https://pubmed.ncbi.nlm.nih.gov/40836398/`]},{key:`flexor-digiti-minimi-brevis`,identities:[[`FMA37471`,`right`,`FJ1391`],[`FMA37472`,`left`,`FJ1391M`]],scope:c,pathology:{body:`Pain near the little-toe base can arise from joint prominence and pressure, including a bunionette; it is not automatically a short-flexor lesion.`,bullets:[`Separate local painful movement from a wider pattern of intrinsic motor weakness.`]},clinical:{body:`This short flexor acts at the fifth metatarsophalangeal joint, not the distal toe joint.`,bullets:[`Use its proximal-phalanx attachment to distinguish it from the long-flexor tendon and the adjacent metatarsal-attaching opponens slip.`]},references:[a,s]},{key:`opponens-digiti-minimi`,identities:[[`FMA86034`,`right`,`FJ1399`],[`FMA86035`,`left`,`FJ1399M`]],scope:`Variable source-labelled slip, not an adjudicated independent muscle, mass or diseased surface.`,pathology:{body:`Variation in whether this slip is separate from flexor digiti minimi brevis should not be labelled an acquired tear or a pathological mass.`,bullets:[`No structure-specific disease pattern has been validated for this atlas entry.`]},clinical:{body:`The retained source label concerns the foot, not the hypothenar muscle of the hand.`,bullets:[`A fifth-metatarsal attachment does not establish thumb-like opposition, an isolated examination manoeuvre or a treatment target.`]},references:[`https://www.kenhub.com/en/library/anatomy/opponens-digiti-minimi-muscle-of-foot`]},{key:`abductor-hallucis`,identities:[[`FMA37459`,`right`,`FJ1400`],[`FMA37460`,`left`,`FJ1400M`]],scope:c,pathology:{body:`Tibial or medial plantar nerve dysfunction can affect this medial intrinsic muscle.`,bullets:[`Medial arch pain by itself does not establish tarsal tunnel syndrome or muscle denervation.`]},clinical:{body:`Relate hallux abduction and flexion to the medial plantar motor supply, alongside sensory symptoms and other muscles.`,bullets:[`This muscle selection is not a nerve-conduction test or a validated tunnel boundary.`]},references:[i,a]},{key:`extensor-hallucis-brevis`,identities:[[`FMA51144`,`right`,`FJ1407`],[`FMA51145`,`left`,`FJ1407M`]],scope:c,pathology:{body:`Loss of great-toe extension can involve local tendon injury or neurological weakness; it cannot be assigned to this short extensor from movement alone.`,bullets:[`A preserved reference surface provides no evidence of tendon integrity in a patient.`]},clinical:{body:`The short extensor acts at the great-toe base; the long extensor reaches the distal phalanx.`,bullets:[`Its deep fibular motor supply differs from plantar intrinsic innervation; this entry does not represent missing short extensors of the lesser toes.`]},references:[a,`https://www.ncbi.nlm.nih.gov/books/NBK554393/`]},{key:`quadratus-plantae`,identities:[[`FMA37465`,`right`,`FJ1412`],[`FMA37466`,`left`,`FJ1412M`]],scope:c,pathology:{body:`Lateral plantar motor dysfunction may involve quadratus plantae alongside other intrinsic muscles.`,bullets:[`Weak toe flexion does not identify an isolated lesion of this muscle.`]},clinical:{body:`Quadratus plantae assists flexion through the long-flexor tendon apparatus, rather than attaching directly to a toe phalanx.`,bullets:[`The source name flexor accessorius refers to this entry; its two heads and individual tendon connections are not separate selections.`]},references:[r,i]},{key:`flexor-digitorum-brevis`,identities:[[`FMA37461`,`right`,`FJ1413`],[`FMA37462`,`left`,`FJ1413M`]],scope:c,pathology:{body:`Lesser-toe deformity reflects the balance of muscles, tendons and joints, not simply shortening or rupture of the short flexor.`,bullets:[`Hammer toe describes a bend at the proximal interphalangeal joint; the diagnosis does not identify one responsible tendon.`]},clinical:{body:`The short flexor reaches the middle phalanges; the long flexor continues to the distal phalanges.`,bullets:[`Compare active movement with passive flexibility; this grouped muscle cannot resolve the integrity of one digital tendon slip.`]},references:[a,o]},{key:`flexor-hallucis-brevis`,identities:[[`FMA45971`,`right`,`FJ1396`],[`FMA45972`,`left`,`FJ1396M`],[`FMA45973`,`right`,`FJ1393`],[`FMA45974`,`left`,`FJ1393M`]],scope:`Shared hallux plantar-complex context for two separately labelled muscle heads; unresolved sesamoid groups are not assigned medial/lateral identity by this lesson.`,pathology:{body:`Turf toe affects the plantar stabilising complex of the first metatarsophalangeal joint; it is not synonymous with an isolated short-flexor tear.`,bullets:[`Pain under the great-toe base may also involve sesamoiditis or a sesamoid fracture; these are different problems.`]},clinical:{body:`Relate push-off and great-toe-base flexion to the short-flexor/sesamoid apparatus, distinct from the long flexor reaching the distal phalanx.`,bullets:[`A bipartite sesamoid can be a normal variant, not automatically a fracture.`,`This selection cannot grade turf toe, prove instability or assign a painful sesamoid to a source muscle head.`]},references:[`https://www.orthoinfo.org/diseases--conditions/turf-toe`,`https://www.orthoinfo.org/diseases--conditions/sesamoiditis/`]},{key:`adductor-hallucis`,identities:[[`FMA46018`,`right`,`FJ1398`],[`FMA46019`,`left`,`FJ1398M`],[`FMA46020`,`right`,`FJ1445`],[`FMA46021`,`left`,`FJ1445M`]],scope:`Shared clinical context for the oblique and transverse heads; neither selection is an independent diseased tendon footprint.`,pathology:{body:`Hallux valgus involves first-ray alignment and soft-tissue mechanics. A bunion is not proof of an isolated adductor-hallucis lesion.`,bullets:[`Inherited foot structure, footwear and inflammatory or neurological disease can contribute.`]},clinical:{body:`Adduction draws the hallux towards the second-toe axis. Both heads contribute to the shared adductor apparatus.`,bullets:[`Standing alignment and joint assessment are different from viewing an unloaded reference model; moving this head in explode mode does not simulate corrective surgery.`]},references:[s,r]}],u=new Map(l.flatMap(e=>e.identities.map(t=>[t[0],{group:e,identity:t}])));function d(e,t){if(t!==`pathology`&&t!==`clinical`||e.system!==`muscles`||e.category!==`muscle`||e.region!==`foot`||e.regions.length!==1||e.regions[0]!==`foot`||e.sourceTree!==`isa`)return;let n=u.get(e.fmaId);if(!n||e.laterality!==n.identity[1]||e.sources.length!==1||e.sources[0].file!==n.identity[2])return;let{group:r}=n,i=r[t];return{readiness:`draft`,title:`${e.name} · ${t===`pathology`?`Injury & disease`:`Clinical context`} · draft`,body:i.body,bullets:[...i.bullets,r.scope],note:[`Draft teaching; independent anatomical and clinical review pending. Educational context, not a patient diagnosis or treatment plan.`,e.coverageNote].filter(Boolean).join(` `),citations:[...r.references]}}var f=[{key:`adductors`,identities:[[`FMA22452`,`right`,`FJ1401`,`thigh`,[`thigh`]],[`FMA22454`,`left`,`FJ1401M`,`thigh`,[`thigh`]],[`FMA22456`,`right`,`FJ1402`,`thigh`,[`thigh`]],[`FMA22457`,`left`,`FJ1402M`,`thigh`,[`thigh`]]],scope:`Reference muscle surface only; no tear, haematoma, compressed nerve or patient scan is represented.`,pathology:{body:`Adductor strains can cause groin or medial-thigh pain after kicking, sprinting or changing direction. Adductor longus is commonly involved.`,bullets:[`Pain may come from the muscle–tendon junction or attachment, not necessarily the visible muscle belly.`]},clinical:{body:`Pain with adductor loading is useful context, but does not identify one muscle or exclude other groin conditions.`,bullets:[`Consider the location, onset and wider hip examination; do not infer tear severity from tenderness alone.`]},references:[`https://www.ncbi.nlm.nih.gov/books/NBK493166/`]},{key:`magnus-minimus`,identities:[[`FMA22459`,`right`,`FJ1403`,`thigh`,[`thigh`]],[`FMA22460`,`left`,`FJ1403M`,`thigh`,[`thigh`]],[`FMA43886`,`right`,`FJ1404`,`thigh`,[`thigh`]],[`FMA43887`,`left`,`FJ1404M`,`thigh`,[`thigh`]]],scope:`Magnus functional portions and the variably separate minimus are not independently mapped motor territories or validated non-overlapping footprints.`,pathology:{body:`Strain-related medial-thigh pain can involve adductor magnus, but its large surface does not imply that every portion is injured.`,bullets:[`Adductor minimus is often described as a superior portion of magnus, rather than a universally separate muscle.`]},clinical:{body:`Distinguish the adductor and hamstring contributions when considering weakness.`,bullets:[`Magnus classically has obturator and tibial/sciatic supply; the entire muscle should not be labelled an isolated obturator-nerve test.`]},references:[`https://www.ncbi.nlm.nih.gov/books/NBK493166/`,`https://www.ncbi.nlm.nih.gov/books/NBK534842/`]},{key:`gracilis`,identities:[[`FMA43883`,`right`,`FJ1421`,`thigh`,[`thigh`]],[`FMA43884`,`left`,`FJ1421M`,`thigh`,[`thigh`]]],scope:`Reference muscle surface only; no tear, haematoma, compressed nerve or patient scan is represented.`,pathology:{body:`Gracilis can be involved in groin strain; its distal tendon also forms part of the pes anserinus at the medial knee.`,bullets:[`Pes anserine bursitis is inflammation of an adjacent bursa, not proof that gracilis has torn.`]},clinical:{body:`Use the level of symptoms to separate proximal adductor-region pain from distal medial-knee pain.`,bullets:[`The shared pes insertion includes sartorius and semitendinosus; these muscles have different proximal attachments and nerve supplies.`]},references:[`https://www.ncbi.nlm.nih.gov/books/NBK493166/`,`https://www.orthoinfo.org/diseases--conditions/pes-anserine-knee-tendon-bursitis`,`https://www.ncbi.nlm.nih.gov/books/NBK534775/`]},{key:`pectineus`,identities:[[`FMA22450`,`right`,`FJ1427`,`thigh`,[`thigh`]],[`FMA22451`,`left`,`FJ1427M`,`thigh`,[`thigh`]]],scope:`Reference muscle surface only; no tear, haematoma, compressed nerve or patient scan is represented.`,pathology:{body:`Pectineus is one possible contributor to adductor-region injury and groin pain.`,bullets:[`A painful groin can also reflect joint, bone or other soft-tissue disease; local symptoms do not identify this small muscle.`]},clinical:{body:`Its combined hip-flexion and adduction role provides context for movement-related symptoms.`,bullets:[`Supply is usually femoral, sometimes with obturator contribution; do not assume that all medial-thigh muscles share one motor nerve.`]},references:[`https://www.ncbi.nlm.nih.gov/books/NBK493166/`,`https://anatomy.ttuhscep.edu/anatomytables/muscles_lowerlimb.html`]},{key:`gemelli-obturator-internus`,identities:[[`FMA22336`,`right`,`FJ1416`,`thigh`,[`thigh`,`pelvis`]],[`FMA22337`,`left`,`FJ1416M`,`thigh`,[`thigh`,`pelvis`]],[`FMA22334`,`right`,`FJ1417`,`thigh`,[`thigh`,`pelvis`]],[`FMA22335`,`left`,`FJ1417M`,`thigh`,[`thigh`,`pelvis`]],[`FMA22324`,`right`,`FJ1426`,`thigh`,[`thigh`,`pelvis`]],[`FMA22325`,`left`,`FJ1426M`,`thigh`,[`thigh`,`pelvis`]]],scope:`These separately labelled muscles share complex-level teaching. No sciatic-nerve tether, compression site or dynamic nerve movement is modelled.`,pathology:{body:`The gemelli–obturator-internus region is one of several anatomical relationships considered in deep gluteal syndromes with buttock or sciatica-like pain.`,bullets:[`This does not establish that every deep external rotator is a cause of nerve entrapment.`]},clinical:{body:`Interpret posterior hip pain alongside lumbar, hip-joint and neurological findings.`,bullets:[`Obturator internus and superior gemellus share a named nerve supply; inferior gemellus instead receives the nerve to quadratus femoris.`]},references:[`https://pubmed.ncbi.nlm.nih.gov/32349600/`,`https://www.ncbi.nlm.nih.gov/books/NBK557420/`]},{key:`obturator-externus`,identities:[[`FMA22326`,`right`,`FJ1425`,`thigh`,[`thigh`,`pelvis`]],[`FMA22327`,`left`,`FJ1425M`,`thigh`,[`thigh`,`pelvis`]]],scope:`Reference muscle surface only; no tear, haematoma, compressed nerve or patient scan is represented.`,pathology:{body:`Obturator externus tears are uncommon reported causes of hip or groin pain. A small football-player series identified these injuries with MRI.`,bullets:[`Pain during rotation overlapped with more commonly suspected adductor or quadriceps injury.`]},clinical:{body:`Deep location can make the injured tissue difficult to identify from symptoms alone.`,bullets:[`A small case series demonstrates a possibility, not prevalence or a universal return-to-sport timetable.`,`Unlike obturator internus, externus is supplied by the obturator nerve.`]},references:[`https://pubmed.ncbi.nlm.nih.gov/36143822/`,`https://anatomy.ttuhscep.edu/anatomytables/muscles_lowerlimb.html`]},{key:`gluteus-maximus`,identities:[[`FMA22328`,`right`,`FJ1418`,`thigh`,[`thigh`,`pelvis`]],[`FMA22329`,`left`,`FJ1418M`,`thigh`,[`thigh`,`pelvis`]]],scope:`Reference muscle surface only; no tear, haematoma, compressed nerve or patient scan is represented.`,pathology:{body:`Inferior gluteal nerve dysfunction can reduce gluteus-maximus strength and hip extension.`,bullets:[`Difficulty rising from a chair or climbing stairs has multiple possible causes and does not diagnose this neuropathy.`]},clinical:{body:`Assess extension strength in the context of pain, other hip muscles and the wider neurological examination.`,bullets:[`Distinguish inferior-gluteal involvement of maximus from superior-gluteal supply to medius, minimus and TFL.`]},references:[`https://www.ncbi.nlm.nih.gov/books/NBK538193/`]},{key:`hip-abductors`,identities:[[`FMA22330`,`right`,`FJ1419`,`thigh`,[`thigh`,`pelvis`]],[`FMA22331`,`left`,`FJ1419M`,`thigh`,[`thigh`,`pelvis`]],[`FMA22332`,`right`,`FJ1420`,`thigh`,[`thigh`,`pelvis`]],[`FMA22333`,`left`,`FJ1420M`,`thigh`,[`thigh`,`pelvis`]]],scope:`Medius/minimus share abductor-tendon context; individual tendon facets, fibre compartments and tear grades are not validated.`,pathology:{body:`Gluteal tendinopathy or tendon tearing can contribute to greater trochanteric pain syndrome, with or without associated bursal disease.`,bullets:[`Lateral hip pain should not automatically be labelled isolated trochanteric bursitis.`]},clinical:{body:`Abductor dysfunction can allow the pelvis to drop on the unsupported side during single-leg stance.`,bullets:[`This pattern concerns the supported hip, but does not by itself distinguish tendon injury, pain inhibition or nerve dysfunction.`,`The reference model does not simulate gait or demonstrate a patient’s abductor tear.`]},references:[`https://www.ncbi.nlm.nih.gov/books/NBK557433/`,`https://www.ncbi.nlm.nih.gov/books/NBK556144/`]},{key:`iliacus`,identities:[[`FMA22322`,`right`,`FJ1422`,`thigh`,[`thigh`,`pelvis`]],[`FMA22323`,`left`,`FJ1422M`,`thigh`,[`thigh`,`pelvis`]]],scope:`Reference muscle surface only; no tear, haematoma, compressed nerve or patient scan is represented.`,pathology:{body:`The shared iliopsoas apparatus can be affected by strain, tendinopathy or painful internal snapping.`,bullets:[`A snapping sensation can also occur without symptoms; it does not automatically mean a tendon tear.`]},clinical:{body:`Relate anterior hip symptoms to the flexor apparatus while considering other groin causes.`,bullets:[`Iliacus and psoas major have separate source identities and different motor supplies despite their shared distal relationship.`]},references:[`https://www.orthoinfo.org/diseases--conditions/hip-strains`,`https://www.orthoinfo.org/diseases--conditions/snapping-hip/`,`https://www.ncbi.nlm.nih.gov/books/NBK531508/`]},{key:`psoas`,identities:[[`FMA22342`,`right`,`FJ1431`,`spine`,[`spine`,`thigh`]],[`FMA22343`,`left`,`FJ1431M`,`spine`,[`spine`,`thigh`]]],scope:`Psoas retains spine and thigh membership. No lumbar-plexus course, abscess, haematoma or vertebral footprint is segmented.`,pathology:{body:`Psoas-region pain can reflect tendon-related disease, but this compartment can also be affected by haematoma or infection.`,bullets:[`Not every painful hip-flexor presentation is a simple strain.`]},clinical:{body:`Assessment may need to consider abdominal, spinal, systemic and neurological findings as well as hip movement.`,bullets:[`Psoas receives direct lumbar branches rather than the femoral motor supply of iliacus.`,`The atlas cannot establish infection, bleeding or a patient-specific cause of pain.`]},references:[`https://www.ncbi.nlm.nih.gov/books/NBK531508/`]},{key:`piriformis`,identities:[[`FMA22340`,`right`,`FJ1428`,`thigh`,[`thigh`,`pelvis`]],[`FMA22341`,`left`,`FJ1428M`,`thigh`,[`thigh`,`pelvis`]]],scope:`Reference muscle surface only; no tear, haematoma, compressed nerve or patient scan is represented.`,pathology:{body:`Piriformis-related sciatic irritation is a possible explanation for some buttock and radiating leg pain.`,bullets:[`Similar symptoms can arise from lumbar or other deep gluteal conditions; sciatica is not synonymous with piriformis syndrome.`]},clinical:{body:`Use this muscle for regional orientation while considering the wider clinical differential.`,bullets:[`Its surface does not prove a sciatic nerve-through-muscle variant, entrapment or the accuracy of a provocative test.`]},references:[`https://www.ncbi.nlm.nih.gov/books/NBK519497/`,`https://pubmed.ncbi.nlm.nih.gov/32349600/`]},{key:`quadratus-femoris`,identities:[[`FMA22338`,`right`,`FJ1432`,`thigh`,[`thigh`,`pelvis`]],[`FMA22339`,`left`,`FJ1432M`,`thigh`,[`thigh`,`pelvis`]]],scope:`Reference muscle surface only; no tear, haematoma, compressed nerve or patient scan is represented.`,pathology:{body:`Ischiofemoral impingement involves the quadratus femoris region between the ischium and lesser trochanter.`,bullets:[`MRI asymmetry and soft-tissue signal changes can also occur in people without symptoms.`]},clinical:{body:`Interpret suspected impingement with symptoms, examination and imaging position rather than a single space measurement.`,bullets:[`Explode displacement changes the teaching layout; it does not measure the anatomical space or demonstrate decompression.`]},references:[`https://pubmed.ncbi.nlm.nih.gov/25680726/`,`https://pubmed.ncbi.nlm.nih.gov/25772723/`]},{key:`sartorius`,identities:[[`FMA22354`,`right`,`FJ1434`,`thigh`,[`thigh`]],[`FMA22355`,`left`,`FJ1434M`,`thigh`,[`thigh`]]],scope:`Reference muscle surface only; no tear, haematoma, compressed nerve or patient scan is represented.`,pathology:{body:`Distal sartorius participates in the pes anserinus, beside a bursa that can become a source of medial-knee pain.`,bullets:[`Bursal pain is different from a sartorius muscle tear or femoral-nerve weakness.`]},clinical:{body:`Localise symptoms relative to the joint line and consider competing knee causes.`,bullets:[`Sartorius crosses the hip and knee but is not one of the hamstring muscles; sharing the pes attachment does not make it a hamstring.`]},references:[`https://www.orthoinfo.org/diseases--conditions/pes-anserine-knee-tendon-bursitis`,`https://www.ncbi.nlm.nih.gov/books/NBK532889/`]},{key:`semimembranosus`,identities:[[`FMA22448`,`right`,`FJ1435`,`thigh`,[`thigh`]],[`FMA22449`,`left`,`FJ1435M`,`thigh`,[`thigh`]]],scope:`Reference muscle surface only; no tear, haematoma, compressed nerve or patient scan is represented.`,pathology:{body:`Semimembranosus can sustain hamstring muscle–tendon injury or proximal attachment injury.`,bullets:[`Acute posterior-thigh pain and bruising do not establish which tendon is damaged.`]},clinical:{body:`Its distal posteromedial tibial attachment differs from the pes anserinus of semitendinosus.`,bullets:[`Distal expansions are not independently segmented here; selecting the surface does not identify every posteromedial-knee structure.`]},references:[`https://www.orthoinfo.org/diseases--conditions/hamstring-muscle-injuries`,`https://www.ncbi.nlm.nih.gov/books/NBK542215/`]},{key:`semitendinosus`,identities:[[`FMA22358`,`right`,`FJ1436`,`thigh`,[`thigh`]],[`FMA22359`,`left`,`FJ1436M`,`thigh`,[`thigh`]]],scope:`Reference muscle surface only; no tear, haematoma, compressed nerve or patient scan is represented.`,pathology:{body:`Semitendinosus can be injured during hamstring loading; its distal tendon is also part of the pes anserinus.`,bullets:[`Proximal hamstring injury and distal pes-region pain are different clinical locations.`]},clinical:{body:`Relate symptoms to the muscle belly, tendon junction or attachment rather than assuming one site.`,bullets:[`Its shared tibial insertion does not make sartorius or gracilis part of the hamstring group.`]},references:[`https://www.orthoinfo.org/diseases--conditions/hamstring-muscle-injuries`,`https://www.orthoinfo.org/diseases--conditions/pes-anserine-knee-tendon-bursitis`,`https://www.ncbi.nlm.nih.gov/books/NBK542215/`]},{key:`tfl`,identities:[[`FMA22425`,`right`,`FJ1438`,`thigh`,[`thigh`]],[`FMA22426`,`left`,`FJ1438M`,`thigh`,[`thigh`]]],scope:`TFL continues into the iliotibial tract. The tract, bursae and dynamic snapping are not separately validated by this muscle surface.`,pathology:{body:`The iliotibial tract can contribute to external snapping over the greater trochanter, sometimes with lateral hip discomfort.`,bullets:[`A snap can be asymptomatic and is not evidence that TFL itself has torn.`]},clinical:{body:`Distinguish external lateral snapping from anterior iliopsoas-related snapping or an intra-articular problem.`,bullets:[`TFL contributes to hip stability through a fascial continuation, not a separately mapped tendon directly joining this muscle to the tibia.`]},references:[`https://www.orthoinfo.org/diseases--conditions/snapping-hip/`,`https://www.ncbi.nlm.nih.gov/books/NBK526019/`]},{key:`rectus-femoris`,identities:[[`FMA38928`,`right`,`FJ1433`,`thigh`,[`thigh`]],[`FMA38929`,`left`,`FJ1433M`,`thigh`,[`thigh`]]],scope:`Proximal heads and the internal tendon are not independent selections or validated injury compartments.`,pathology:{body:`Rectus femoris can sustain muscle–tendon strain during activities loading hip flexion and knee extension.`,bullets:[`A proximal injury is different from disruption of the shared quadriceps tendon near the patella.`]},clinical:{body:`Rectus crosses both the hip and knee; the vasti do not cross the hip.`,bullets:[`The injury location matters when interpreting pain and weakness; no injury grade or rehabilitation timeline is encoded here.`]},references:[`https://www.orthoinfo.org/diseases--conditions/hip-strains`,`https://www.ncbi.nlm.nih.gov/books/NBK513334/`]},{key:`vasti`,identities:[[`FMA38930`,`right`,`FJ1442`,`thigh`,[`thigh`]],[`FMA38931`,`left`,`FJ1442M`,`thigh`,[`thigh`]],[`FMA38932`,`right`,`FJ1443`,`thigh`,[`thigh`]],[`FMA38933`,`left`,`FJ1443M`,`thigh`,[`thigh`]],[`FMA38934`,`right`,`FJ1441`,`thigh`,[`thigh`]],[`FMA38935`,`left`,`FJ1441M`,`thigh`,[`thigh`]]],scope:`The three vasti share extensor-mechanism context; selecting one does not independently validate its contribution to a shared tendon tear.`,pathology:{body:`A quadriceps-tendon tear disrupts force transmission to the patella. Complete disruption can cause major loss of active knee extension.`,bullets:[`Muscle strain, shared tendon injury and neurological weakness are different mechanisms.`]},clinical:{body:`A new inability to straighten the knee after injury warrants prompt clinical assessment.`,bullets:[`Neither vastus medialis fibre subdivisions nor a separate tear in each vastus are represented.`,`The quadriceps tendon lies above the patella; it is not the patellar tendon below it.`]},references:[`https://www.orthoinfo.org/diseases--conditions/quadriceps-tendon-tear`,`https://www.ncbi.nlm.nih.gov/books/NBK513334/`]},{key:`biceps-long`,identities:[[`FMA45888`,`right`,`FJ1395`,`thigh`,[`thigh`]],[`FMA45889`,`left`,`FJ1395M`,`thigh`,[`thigh`]]],scope:`One head is selected; the shared distal biceps tendon and proximal avulsion are not independently reconstructed.`,pathology:{body:`The long head can be affected by hamstring strain or an avulsion involving its proximal ischial attachment.`,bullets:[`An avulsion detaches a tendon from bone and may include a bony fragment; it is not just muscle soreness.`]},clinical:{body:`This head crosses both hip and knee and receives the tibial division of the sciatic nerve.`,bullets:[`Its proximal attachment and motor supply differ from the short head; shared distal attachment does not make their injuries identical.`]},references:[`https://www.orthoinfo.org/diseases--conditions/hamstring-muscle-injuries`,`https://www.ncbi.nlm.nih.gov/books/NBK546688/`]},{key:`biceps-short`,identities:[[`FMA45891`,`right`,`FJ1444`,`thigh`,[`thigh`]],[`FMA45892`,`left`,`FJ1444M`,`thigh`,[`thigh`]]],scope:`Reference muscle surface only; no tear, haematoma, compressed nerve or patient scan is represented.`,pathology:{body:`Pain or weakness involving the short head must be distinguished from proximal ischial hamstring injury.`,bullets:[`The short head arises from the femur and has no ischial origin to avulse.`]},clinical:{body:`It contributes to knee flexion but does not cross or extend the hip.`,bullets:[`Its motor supply is from the common fibular division of the sciatic nerve, unlike the tibial supply to the long head.`,`The selected head cannot independently localise a sciatic lesion or establish tendon continuity.`]},references:[`https://www.ncbi.nlm.nih.gov/books/NBK546688/`]}],p=new Map(f.flatMap(e=>e.identities.map(t=>[t[0],{group:e,identity:t}])));function m(e,t){if(t!==`pathology`&&t!==`clinical`||e.system!==`muscles`||e.category!==`muscle`||e.sourceTree!==`isa`)return;let n=p.get(e.fmaId);if(!n||e.laterality!==n.identity[1]||e.sources.length!==1||e.sources[0].file!==n.identity[2]||e.region!==n.identity[3]||e.regions.length!==n.identity[4].length||e.regions.some((e,t)=>e!==n.identity[4][t]))return;let{group:r}=n,i=r[t];return{readiness:`draft`,title:`${e.name} · ${t===`pathology`?`Injury & disease`:`Clinical context`} · draft`,body:i.body,bullets:[...i.bullets,r.scope],note:[`Draft teaching; independent anatomical and clinical review pending. Educational context, not a patient diagnosis or treatment plan.`,e.coverageNote].filter(Boolean).join(` `),citations:[...r.references]}}var h=[{key:`clavicle`,identities:[[`FMA13323`,`left`,`isa`,[`FJ3237`],`shoulder-arm`,[`shoulder-arm`]]],scope:`Whole reference clavicle, not separated fracture fragments, a ligament reconstruction or a map of subclavian neurovascular clearance.`,pathology:{body:`A clavicle fracture is a break in bone; an acromioclavicular separation or sternoclavicular dislocation concerns a joint. These are not interchangeable labels.`,bullets:[`Skin tenting or an open wound after injury can indicate threatened soft tissues; clinical assessment must include the skin and the limb circulation and nerves.`]},clinical:{body:`Trace the sternal and acromial ends before relating a painful area to the shaft or either joint.`,bullets:[`The clavicle overlies important nerves and vessels. Their proximity indicates a reason for assessment, not proof of injury in every fracture.`]},references:[`https://www.orthoinfo.org/diseases--conditions/clavicle-fracture-broken-collarbone/`]},{key:`scapula`,identities:[[`FMA13396`,`left`,`isa`,[`FJ3279`],`shoulder-arm`,[`shoulder-arm`]]],scope:`Body, neck and glenoid are parts of one intact source mesh. No fracture line, joint-surface step or chest injury is represented.`,pathology:{body:`Scapular fractures after high-energy trauma may accompany chest and other injuries; a scapular selection must not narrow assessment to one bone.`,bullets:[`A glenoid fracture involves the shoulder socket. A scapular-body fracture is not automatically an articular injury.`]},clinical:{body:`Identify the glenoid separately from the blade and neck when describing the location of a fracture.`,bullets:[`Patient imaging establishes extension and displacement. An explode gap is a teaching arrangement, not glenohumeral dislocation.`]},references:[`https://www.orthoinfo.org/diseases--conditions/scapula-shoulder-blade-fractures/`]},{key:`humerus`,identities:[[`FMA23131`,`left`,`isa`,[`FJ3262`],`shoulder-arm`,[`shoulder-arm`,`forearm`]]],scope:`Adult reference bone only; no nerve lesion, fracture displacement, paediatric growth plate or fixation corridor is simulated.`,pathology:{body:`Fracture location changes the associated structures of concern: the axillary nerve near the surgical neck differs from the radial nerve near the shaft.`,bullets:[`Radial-nerve injury can weaken wrist and finger extension; it is a possible association, not an inevitable consequence of a humeral fracture.`]},clinical:{body:`Describe proximal, shaft or distal involvement before considering adjacent joints and neurovascular findings.`,bullets:[`A clinical motor, sensory and circulation examination cannot be replaced by the normal mesh. Keep surgical neck distinct from anatomical neck.`]},references:[`https://www.ncbi.nlm.nih.gov/books/NBK448074/`]},{key:`radius`,identities:[[`FMA23465`,`left`,`isa`,[`FJ3277`],`forearm`,[`forearm`]],[`FMA23464`,`right`,`isa`,[`FJ3349`],`forearm`,[`forearm`]]],scope:`An intact adult radius does not establish distal radioulnar stability, interosseous-membrane integrity or patient forearm rotation.`,pathology:{body:`A Galeazzi fracture-dislocation combines a radial shaft fracture with disruption/dislocation at the distal radioulnar joint; it is not simply a distal-radius wrist fracture.`,bullets:[`Both forearm bones and the elbow and wrist relationships matter when assessing a shaft injury.`]},clinical:{body:`Follow the radius from the radial head to the wrist; localise the fracture before naming the associated joint injury.`,bullets:[`For forearm-shaft trauma, imaging assessment includes elbow and wrist as well as the shaft. The atlas provides orientation, not diagnostic radiographs.`]},references:[`https://surgeryreference.aofoundation.org/orthopedic-trauma/adult-trauma/forearm-shaft/simple-fracture-of-the-radius-with-dislocation-of-distal-radioulnar-joint-galeazzi/orif-plating`,`https://surgeryreference.aofoundation.org/orthopedic-trauma/adult-trauma/forearm-shaft/further-reading/clinical-and-radiographic-examination`]},{key:`ulna`,identities:[[`FMA23468`,`left`,`isa`,[`FJ3286`],`forearm`,[`forearm`]],[`FMA23467`,`right`,`isa`,[`FJ3391`],`forearm`,[`forearm`]]],scope:`This whole adult ulna does not demonstrate radial-head alignment under load or annular-ligament integrity.`,pathology:{body:`A Monteggia fracture-dislocation combines an ulnar fracture with radial-head dislocation. Focusing only on the visible ulnar break can miss the joint injury.`,bullets:[`Contrast the proximal radial-head association with the distal radioulnar-joint injury in a Galeazzi pattern.`]},clinical:{body:`Use the olecranon and proximal ulna to orient the elbow, then inspect the relationship of the separate radial head to the humerus.`,bullets:[`An apparently aligned static reference cannot exclude a fracture-dislocation in a patient; clinical forearm-shaft assessment includes both adjacent joints.`]},references:[`https://surgeryreference.aofoundation.org/orthopedic-trauma/adult-trauma/forearm-shaft/basic-technique/radial-head-stabilization-monteggia-fracture-dislocation`,`https://surgeryreference.aofoundation.org/orthopedic-trauma/adult-trauma/forearm-shaft/further-reading/clinical-and-radiographic-examination`]},{key:`hip-bone`,identities:[[`FMA16586`,`right`,`isa`,[`FJ3152`],`pelvis`,[`pelvis`,`thigh`]],[`FMA16587`,`left`,`isa`,[`FJ3288`],`pelvis`,[`pelvis`,`thigh`]]],scope:`One hip bone is not the complete pelvic ring. Neither ligament competence, bleeding, bone density nor a patient-specific acetabular fracture is modelled.`,pathology:{body:`Pelvic-ring injury and an acetabular fracture describe different anatomical problems: one concerns the ring, the other the hip socket. They can coexist.`,bullets:[`High-energy pelvic injury may cause serious bleeding and associated organ injury and requires emergency assessment.`]},clinical:{body:`Distinguish the socket in the hip bone from the femoral head and neck. Evaluate pelvic stability in the context of the whole ring and its ligamentous connections.`,bullets:[`For acetabular injury, location within the socket and joint congruity matter; a smooth atlas surface cannot show patient cartilage damage or displacement.`]},references:[`https://www.orthoinfo.org/diseases--conditions/pelvic-fractures?webid=2FDEE455`,`https://www.orthoinfo.org/diseases--conditions/acetabular-fractures/`]},{key:`femur`,identities:[[`FMA24475`,`left`,`isa`,[`FJ3259`],`thigh`,[`thigh`,`pelvis`,`leg`]],[`FMA24474`,`right`,`isa`,[`FJ3365`],`thigh`,[`thigh`,`pelvis`,`leg`]]],scope:`The single femur spans hip, thigh and knee routes; it contains no patient fracture, marrow oedema, bone-density measurement or growth-plate assessment.`,pathology:{body:`A hip fracture usually refers to the proximal femur, not the acetabulum. Femoral-neck, intertrochanteric and subtrochanteric locations are distinct.`,bullets:[`Some nondisplaced hip fractures still permit painful weight-bearing; the ability to stand does not exclude a fracture.`]},clinical:{body:`Locate the head, neck and trochanteric region before describing proximal injury; keep these separate from shaft or distal-femoral injuries.`,bullets:[`A fracture can be occult on initial radiographs. Ongoing clinical suspicion requires assessment and appropriate further imaging, not reassurance from a normal atlas.`]},references:[`https://www.orthoinfo.org/diseases--conditions/hip-fractures/`]},{key:`tibia`,identities:[[`FMA24478`,`left`,`isa`,[`FJ3282`],`leg`,[`leg`]],[`FMA24477`,`right`,`isa`,[`FJ3387`],`leg`,[`leg`]]],scope:`No depressed joint surface, fracture fragment, meniscal lesion, ligament tear or compartment pressure is present in this reference tibia.`,pathology:{body:`A tibial-plateau fracture extends into the knee joint; some proximal tibial fractures do not enter the joint. Articular injury and shaft injury are not equivalent.`,bullets:[`Associated soft-tissue swelling can threaten muscle and nerve blood supply through compartment syndrome, a medical emergency.`]},clinical:{body:`Relate the plateau to the femoral condyles, then distinguish articular alignment from the condition of surrounding soft tissues.`,bullets:[`The extent of an injury depends on patient examination and imaging. A well-aligned bone alone does not establish a stable, uninjured knee.`]},references:[`https://www.orthoinfo.org/en/diseases--conditions/fractures-of-the-proximal-tibia-shinbone/`]},{key:`fibula`,identities:[[`FMA24481`,`left`,`isa`,[`FJ3260`],`leg`,[`leg`]],[`FMA24480`,`right`,`isa`,[`FJ3366`],`leg`,[`leg`]]],scope:`Neither distal tibiofibular ligament integrity nor ankle stability is inferred from the intact fibular mesh or its explode position.`,pathology:{body:`A proximal fibular fracture can be part of a wider ankle injury involving the syndesmosis and medial structures; distance from the ankle does not make it irrelevant.`,bullets:[`Do not assume every proximal fibular fracture has this pattern, or assess a suspected ankle injury from the lateral malleolus alone.`]},clinical:{body:`Follow the entire fibula rather than examining only its distal tip. Interpret its position alongside tibial, talar and ligamentous relationships.`,bullets:[`Normal reference spacing cannot exclude syndesmotic disruption. No stress examination, treatment choice or fixation technique is supplied.`]},references:[`https://surgeryreference.aofoundation.org/orthopedic-trauma/adult-trauma/malleoli/suprasyndesmotic-proximal-fibular-fracture-medial-injury-posterior-fracture/definition`]},{key:`patella`,identities:[[`FMA24487`,`left`,`isa`,[`FJ3275`],`leg`,[`leg`]],[`FMA24486`,`right`,`isa`,[`FJ3381`],`leg`,[`leg`]]],scope:`No patellar fracture, cartilage defect, quadriceps/patellar-tendon continuity or dynamic tracking is simulated.`,pathology:{body:`A patellar fracture may impair active knee extension and damage the joint surface; its clinical importance is not just the number of bone fragments.`,bullets:[`Difficulty straightening the knee or raising the straight leg after injury prompts assessment of the extensor mechanism and the injury as a whole.`]},clinical:{body:`Relate the patella to the quadriceps tendon above, patellar tendon below and femoral articular surface behind.`,bullets:[`A bone-only selection cannot test active extension or determine the integrity of the surrounding tendons and retinacula.`]},references:[`https://www.orthoinfo.org/diseases--conditions/patellar-kneecap-fractures/`]}],g=new Map(h.flatMap(e=>e.identities.map(t=>[t[0],{group:e,identity:t}]))),_=(e,t)=>e.length===t.length&&e.every((e,n)=>e===t[n]);function v(e,t){if(t!==`pathology`&&t!==`clinical`||e.system!==`skeleton`||e.category!==`bone`)return;let n=g.get(e.fmaId);if(!n)return;let[,r,i,a,o,s]=n.identity;if(e.laterality!==r||e.sourceTree!==i||e.region!==o||!_(e.regions,s)||!_(e.sources.map(e=>e.file),a))return;let{group:c}=n,l=c[t];return{readiness:`draft`,title:`${e.name} · ${t===`pathology`?`Injury & disease`:`Clinical context`} · draft`,body:l.body,bullets:[...l.bullets,c.scope],note:[`Draft teaching; independent anatomical and clinical review pending. Educational context, not a patient diagnosis or treatment plan.`,e.coverageNote].filter(Boolean).join(` `),citations:[...c.references]}}var y=[{key:`scaphoid`,identities:[[`FMA24436`,`left`,`isa`,[`FJ3278`],`hand`,[`hand`]],[`FMA24435`,`right`,`isa`,[`FJ3383`],`hand`,[`hand`]]],scope:`One intact scaphoid per side; no fracture line, perfusion, nonunion or scapholunate-ligament lesion is reconstructed.`,pathology:{body:`Scaphoid fractures may be invisible on initial radiographs. Disrupted blood supply, particularly towards the proximal fragment, can complicate healing.`,bullets:[`A normal early X-ray does not exclude a clinically suspected scaphoid fracture; persistent symptoms need assessment and an appropriate imaging plan.`]},clinical:{body:`Distinguish the proximal pole, waist and distal pole when describing the injury, rather than treating all scaphoid fractures as equivalent.`,bullets:[`CT and MRI can answer different questions about fracture configuration and occult injury; this reference surface does not measure blood flow or prove healing.`]},references:[`https://www.orthoinfo.org/diseases--conditions/scaphoid-fracture-of-the-wrist`,`https://www.bssh.ac.uk/_userfiles/pages/files/professionals/Trauma%20standards/Scaphoid%20standards.pdf`]},{key:`lunate`,identities:[[`FMA24438`,`left`,`isa`,[`FJ3268`],`hand`,[`hand`]],[`FMA24437`,`right`,`isa`,[`FJ3374`],`hand`,[`hand`]]],scope:`This normal lunate has no marrow/perfusion data or simulated collapse. Kienböck disease is not synonymous with traumatic lunate dislocation.`,pathology:{body:`Kienböck disease involves osteonecrosis of the lunate. Its cause is multifactorial; a short ulna or one wrist shape does not by itself establish the diagnosis.`,bullets:[`Early radiographs may appear normal. Symptoms, examination and appropriate imaging are needed to distinguish it from other causes of wrist pain.`]},clinical:{body:`Relate the lunate to the radius and neighbouring carpals, keeping bone viability separate from joint alignment.`,bullets:[`Selecting or moving this bone cannot diagnose osteonecrosis, assign a disease stage or evaluate a patient's carpal stability.`]},references:[`https://www.assh.org/handcareprod/condition/kienbocks-disease`]},{key:`triquetrum`,identities:[[`FMA24440`,`left`,`isa`,[`FJ3285`],`hand`,[`hand`]],[`FMA24439`,`right`,`isa`,[`FJ3390`],`hand`,[`hand`]]],scope:`The triquetrum and the palmar pisiform remain distinct bones. No dorsal fragment or ligament avulsion is drawn.`,pathology:{body:`A triquetral fracture may be isolated or part of a more extensive carpal injury involving other bones and ligaments.`,bullets:[`Finding one fracture does not exclude an accompanying ligament injury.`]},clinical:{body:`Inspect its proximal-row relationships and the separate pisotriquetral articulation when orienting ulnar-sided wrist injury.`,bullets:[`Explode separation is not traumatic carpal displacement or a test of wrist stability.`]},references:[`https://surgeryreference.aofoundation.org/orthopedic-trauma/adult-trauma/carpal-bones/perilunate-fracture-dislocation/definition`]},{key:`pisiform`,identities:[[`FMA24442`,`left`,`isa`,[`FJ3276`],`hand`,[`hand`]],[`FMA24441`,`right`,`isa`,[`FJ3382`],`hand`,[`hand`]]],scope:`The pisiform is a sesamoid in the flexor carpi ulnaris tendon, not a phalanx. Adjacent ulnar nerve and artery clearance is unvalidated.`,pathology:{body:`Pisiform fractures can occur in isolation or within a complex wrist injury. Palmar-ulnar wrist symptoms should not automatically be assigned to the bone alone.`,bullets:[`Nearby nerve, vessel and tendon findings remain separate clinical questions.`]},clinical:{body:`Distinguish the pisiform from the triquetrum behind it and the hamate hook farther distally.`,bullets:[`This bony landmark does not establish a safe Guyon-canal corridor or demonstrate tendon or nerve integrity.`]},references:[`https://surgeryreference.aofoundation.org/orthopedic-trauma/adult-trauma/carpal-bones/perilunate-fracture-dislocation/definition`,`https://surgeryreference.aofoundation.org/orthopedic-trauma/adult-trauma/carpal-bones/approach/ulnar-approach-to-the-hamate-hook`]},{key:`trapezium`,identities:[[`FMA24444`,`left`,`isa`,[`FJ3283`],`hand`,[`hand`]],[`FMA24443`,`right`,`isa`,[`FJ3388`],`hand`,[`hand`]]],scope:`The trapezium is not the trapezoid. Thumb-base joint cartilage, contact mechanics and painful loading are not modelled.`,pathology:{body:`Basal thumb osteoarthritis affects the joint between the trapezium and first metacarpal. Radiographic changes do not always correspond to substantial pain.`,bullets:[`The joint surface and symptoms matter; it is not simply a disorder of one isolated carpal bone.`]},clinical:{body:`Relate the trapezium to the first metacarpal when studying painful pinch or grip at the thumb base.`,bullets:[`The atlas cannot grade cartilage loss, test a painful joint or determine whether surgery is needed.`]},references:[`https://www.bssh.ac.uk/patients/conditions/24/basal_thumb_arthritis`]},{key:`central-carpals`,identities:[[`FMA24447`,`left`,`isa`,[`FJ3257`],`hand`,[`hand`]],[`FMA24445`,`left`,`isa`,[`FJ3284`],`hand`,[`hand`]],[`FMA24446`,`right`,`isa`,[`FJ3361`],`hand`,[`hand`]],[`FMA23725`,`right`,`isa`,[`FJ3389`],`hand`,[`hand`]]],scope:`Capitate and trapezoid retain separate identities and central/index-ray relationships. No carpal arc, ligament competence or fracture displacement is measured.`,pathology:{body:`Central carpal fractures may accompany complex fracture-dislocations. Bony and ligamentous injuries can coexist rather than being mutually exclusive alternatives.`,bullets:[`An isolated reference bone cannot show the full extent of a patient's carpal injury.`]},clinical:{body:`Study the selected bone with its neighbouring carpal row and metacarpal base, not only as a detached object.`,bullets:[`Arrangement controls move normal surfaces for teaching; they do not reproduce an injury classification or validate clinical alignment.`]},references:[`https://surgeryreference.aofoundation.org/orthopedic-trauma/adult-trauma/carpal-bones/perilunate-fracture-dislocation/definition`]},{key:`hamate`,identities:[[`FMA24449`,`left`,`isa`,[`FJ3261`],`hand`,[`hand`]],[`FMA24448`,`right`,`isa`,[`FJ3367`],`hand`,[`hand`]]],scope:`The hook and body are parts of one hamate selection. There is no separately validated hook fracture, Guyon-canal lesion or tendon corridor.`,pathology:{body:`A hamate fracture can place nearby ulnar nerve structures at risk. Hook injury and injury involving the body or metacarpal-base articulations are not the same pattern.`,bullets:[`Numbness or hand weakness requires clinical assessment; a bone selection cannot identify the affected nerve branch.`]},clinical:{body:`Relate the hook to the palmar-ulnar wrist and the body to the fourth and fifth metacarpal bases.`,bullets:[`Neither absence of a modelled nerve nor a visible gap between meshes establishes neurovascular safety.`]},references:[`https://surgeryreference.aofoundation.org/orthopedic-trauma/adult-trauma/further-reading/hand-ulnar-and-median-nerve-lesions`,`https://surgeryreference.aofoundation.org/orthopedic-trauma/adult-trauma/carpal-bones/hamate-hook/orif-screw-fixation`]},{key:`thumb-metacarpal`,identities:[[`FMA24465`,`left`,`isa`,[`FJ3240`],`hand`,[`hand`]],[`FMA24464`,`right`,`isa`,[`FJ3350`],`hand`,[`hand`]]],scope:`One first metacarpal per side. The carpometacarpal base and metacarpophalangeal head are separate joint regions, not a single thumb joint.`,pathology:{body:`Fractures extending into the thumb-base joint, including Bennett and Rolando patterns, differ from extra-articular shaft or base fractures.`,bullets:[`A fracture's relationship to the joint is important; the label 'thumb fracture' does not specify its configuration.`]},clinical:{body:`Locate the base against the trapezium before distinguishing it from the metacarpal head at the knuckle.`,bullets:[`No fragment pattern, stability grade or treatment indication is supplied by this intact reference bone.`]},references:[`https://www.orthoinfo.org/diseases--conditions/thumb-fractures`]},{key:`central-metacarpals`,identities:[[`FMA24467`,`left`,`isa`,[`FJ3243`],`hand`,[`hand`]],[`FMA24469`,`left`,`isa`,[`FJ3246`],`hand`,[`hand`]],[`FMA24471`,`left`,`isa`,[`FJ3249`],`hand`,[`hand`]],[`FMA24466`,`right`,`isa`,[`FJ3352`],`hand`,[`hand`]],[`FMA24468`,`right`,`isa`,[`FJ3354`],`hand`,[`hand`]],[`FMA24470`,`right`,`isa`,[`FJ3356`],`hand`,[`hand`]]],scope:`Each second, third and fourth metacarpal keeps its own digit and side. The model does not measure shortening, rotational deformity or grip.`,pathology:{body:`Metacarpal fractures can alter length, angulation and rotation. Finger overlap during flexion may reveal a functional problem that is less obvious with the fingers straight.`,bullets:[`Joint, tendon, skin and sensory assessment is needed alongside the bone injury.`]},clinical:{body:`Distinguish the carpal base, shaft and knuckle end, and consider the entire digit rather than only its metacarpal.`,bullets:[`Exploding the hand is not a malrotation test and does not define acceptable deformity or a reduction technique.`]},references:[`https://www.orthoinfo.org/diseases--conditions/hand-fractures/`]},{key:`fifth-metacarpal`,identities:[[`FMA24473`,`left`,`isa`,[`FJ3252`],`hand`,[`hand`]],[`FMA24472`,`right`,`isa`,[`FJ3358`],`hand`,[`hand`]]],scope:`The fifth metacarpal is not the little finger's proximal phalanx. Its base, shaft, neck and head are not separate selectable fracture fragments.`,pathology:{body:`A boxer's fracture usually describes a fifth-metacarpal neck fracture near the knuckle, not every injury to the fifth metacarpal.`,bullets:[`The name does not prove that punching caused the injury; falls and other trauma can also produce this pattern.`]},clinical:{body:`Keep a neck injury distinct from a base injury at the carpometacarpal joint, and assess the associated finger alignment clinically.`,bullets:[`This normal source neither shows a depressed knuckle nor sets an acceptable angulation or return-to-activity threshold.`]},references:[`https://www.orthoinfo.org/diseases--conditions/hand-fractures/`]},{key:`thumb-proximal-phalanx`,identities:[[`FMA65470`,`left`,`isa`,[`FJ3318`],`hand`,[`hand`]],[`FMA24450`,`right`,`isa`,[`FJ3327`],`hand`,[`hand`]]],scope:`The thumb has one interphalangeal joint and no middle phalanx. No collateral ligament, Stener lesion or stress examination is simulated.`,pathology:{body:`A thumb MCP ulnar-collateral-ligament injury may include a bony avulsion. A ligament tear and a fracture at its attachment are related but distinct findings.`,bullets:[`A normal-looking bone does not establish that the MCP ligament is intact.`]},clinical:{body:`Relate the proximal phalanx to the metacarpal head when considering instability or weakness during pinch.`,bullets:[`Clinical examination and imaging are required; do not use the separation control to stress an injured thumb or infer ligament stability.`]},references:[`https://www.orthoinfo.org/diseases--conditions/sprained-thumb`]},{key:`finger-proximal-phalanges`,identities:[[`FMA71915`,`left`,`isa`,[`FJ3313`],`hand`,[`hand`]],[`FMA66791`,`left`,`isa`,[`FJ3314`],`hand`,[`hand`]],[`FMA71908`,`left`,`isa`,[`FJ3316`],`hand`,[`hand`]],[`FMA71916`,`left`,`isa`,[`FJ3317`],`hand`,[`hand`]],[`FMA24451`,`right`,`isa`,[`FJ3322`],`hand`,[`hand`]],[`FMA24454`,`right`,`isa`,[`FJ3323`],`hand`,[`hand`]],[`FMA24452`,`right`,`isa`,[`FJ3325`],`hand`,[`hand`]],[`FMA24453`,`right`,`isa`,[`FJ3326`],`hand`,[`hand`]]],scope:`Each proximal phalanx connects an MCP and a PIP region. Side, digit and segment remain exact; no tendon excursion or joint cartilage is validated.`,pathology:{body:`Finger fractures can produce rotational deformity or involve a joint surface. Even a small bone injury can impair the function of the whole hand.`,bullets:[`Clinical assessment considers finger overlap, motion and adjacent soft tissues rather than the fracture image alone.`]},clinical:{body:`Follow the digit from its metacarpal through the proximal and middle phalanges when describing alignment.`,bullets:[`Reference mesh orientation is not a patient finger cascade, a fracture reduction target or evidence of normal tendon function.`]},references:[`https://www.orthoinfo.org/diseases--conditions/finger-fractures`]},{key:`finger-middle-phalanges`,identities:[[`FMA23942`,`left`,`isa`,[`FJ3291`],`hand`,[`hand`]],[`FMA24457`,`right`,`isa`,[`FJ3292`],`hand`,[`hand`]],[`FMA23938`,`left`,`isa`,[`FJ3296`],`hand`,[`hand`]],[`FMA23944`,`left`,`isa`,[`FJ3297`],`hand`,[`hand`]],[`FMA23940`,`left`,`isa`,[`FJ3299`],`hand`,[`hand`]],[`FMA24455`,`right`,`isa`,[`FJ3303`],`hand`,[`hand`]],[`FMA24458`,`right`,`isa`,[`FJ3304`],`hand`,[`hand`]],[`FMA24456`,`right`,`isa`,[`FJ3306`],`hand`,[`hand`]]],scope:`Middle phalanges exist in digits 2–5, not the thumb. The dorsal central slip and palmar volar plate are different, unvalidated soft-tissue attachments.`,pathology:{body:`Hyperextension can injure the PIP volar plate, with or without a bony avulsion. Central-slip injury affects the extensor mechanism and may lead to a boutonnière pattern.`,bullets:[`A volar-plate injury and a central-slip injury are not interchangeable explanations for a bent or painful finger.`]},clinical:{body:`Orient the palmar and dorsal sides of the PIP region separately while keeping the distal DIP joint distinct.`,bullets:[`The atlas does not perform tendon testing, reproduce an avulsed fragment or decide a splint position.`]},references:[`https://www.bssh.ac.uk/patients/conditions/1021/volar_plate_injury`,`https://www.bssh.ac.uk/patients/conditions/29/boutonniere_injury`]},{key:`finger-distal-phalanges`,identities:[[`FMA23953`,`left`,`isa`,[`FJ3183`],`hand`,[`hand`]],[`FMA23959`,`left`,`isa`,[`FJ3184`],`hand`,[`hand`]],[`FMA23955`,`left`,`isa`,[`FJ3186`],`hand`,[`hand`]],[`FMA23957`,`left`,`isa`,[`FJ3187`],`hand`,[`hand`]],[`FMA24460`,`right`,`isa`,[`FJ3193`],`hand`,[`hand`]],[`FMA24463`,`right`,`isa`,[`FJ3194`],`hand`,[`hand`]],[`FMA24461`,`right`,`isa`,[`FJ3196`],`hand`,[`hand`]],[`FMA24462`,`right`,`isa`,[`FJ3197`],`hand`,[`hand`]]],scope:`The distal phalanx and its DIP joint remain separate from the nail bed and terminal extensor tendon. No tendon discontinuity or fragment is modelled.`,pathology:{body:`Mallet injury disrupts the terminal extensor mechanism, sometimes with an avulsed bone fragment. It can therefore occur with or without a visible fracture.`,bullets:[`Loss of active fingertip extension is a functional finding, not a diagnosis made from bone shape alone.`]},clinical:{body:`Distinguish dorsal-base avulsion context from a crush injury of the tuft or nail bed.`,bullets:[`No splinting schedule or operative threshold is inferred from this intact reference surface.`]},references:[`https://www.orthoinfo.org/diseases--conditions/mallet-finger-baseball-finger`,`https://www.orthoinfo.org/diseases--conditions/fingertip-injuries-and-amputations/`]},{key:`thumb-distal-phalanx`,identities:[[`FMA23951`,`left`,`isa`,[`FJ3188`],`hand`,[`hand`]],[`FMA24459`,`right`,`isa`,[`FJ3198`],`hand`,[`hand`]]],scope:`This is the thumb's terminal phalanx at its IP joint, not a finger DIP or middle phalanx. Nail bed, pulp and tendon integrity are not shown.`,pathology:{body:`A thumb-tip crush injury may affect bone, nail bed and surrounding soft tissues together. A small bony injury does not establish the severity of the whole fingertip injury.`,bullets:[`Blood beneath a nail and a fracture are different findings; the atlas cannot assess either in a patient.`]},clinical:{body:`Relate the terminal bone to the proximal phalanx and the fingertip tissues without assuming that an intact outline means an intact tendon or nail bed.`,bullets:[`Open wounds, sensation and circulation require examination; no nail-drainage or wound-treatment procedure is provided.`]},references:[`https://www.orthoinfo.org/diseases--conditions/fingertip-injuries-and-amputations/`,`https://www.orthoinfo.org/diseases--conditions/thumb-fractures`]},{key:`talus`,identities:[[`FMA24483`,`left`,`isa`,[`FJ3280`],`foot`,[`foot`]],[`FMA24482`,`right`,`isa`,[`FJ3385`],`foot`,[`foot`]]],scope:`The talar head, neck and body remain one intact source. Ankle and subtalar joints are distinct; no perfusion, collapse or patient fracture is simulated.`,pathology:{body:`Talar fractures may disrupt the blood supply and can lead to osteonecrosis. Joint-cartilage damage may also cause post-traumatic arthritis even when a fracture heals.`,bullets:[`These complications are risks, not inevitable outcomes of every talar fracture.`]},clinical:{body:`Consider the talus with the ankle mortise, calcaneus and navicular, distinguishing the joint surfaces involved.`,bullets:[`The atlas cannot determine bone viability, fracture healing or a safe weight-bearing plan.`]},references:[`https://www.orthoinfo.org/diseases--conditions/talus-fractures`]},{key:`calcaneus`,identities:[[`FMA24498`,`left`,`isa`,[`FJ3256`],`foot`,[`foot`]],[`FMA24497`,`right`,`isa`,[`FJ3360`],`foot`,[`foot`]]],scope:`An intact heel bone, not a reconstruction of joint depression, heel widening or Achilles avulsion. Skin and soft-tissue injury are not measured.`,pathology:{body:`Calcaneal fractures can involve the subtalar joint and surrounding soft tissues. A high-energy heel injury may also be accompanied by injuries elsewhere, including the spine.`,bullets:[`An associated injury is possible, not proved by the heel-fracture label.`]},clinical:{body:`Separate the calcaneal body, posterior heel and subtalar relationship when describing the injury.`,bullets:[`Normal reference shape does not establish preserved cartilage, exclude another injury or predict walking function after a fracture.`]},references:[`https://www.orthoinfo.org/diseases--conditions/calcaneus-heel-bone-fractures/`]},{key:`navicular`,identities:[[`FMA24501`,`left`,`isa`,[`FJ3307`],`foot`,[`foot`]],[`FMA24500`,`right`,`isa`,[`FJ3308`],`foot`,[`foot`]]],scope:`The foot navicular is not the wrist scaphoid. No stress-fracture line, accessory navicular, marrow change or vascular study is included.`,pathology:{body:`Repetitive loading can cause a navicular stress fracture with gradually developing midfoot pain. Early radiographs may appear normal.`,bullets:[`Persistent symptoms require clinical assessment; CT or MRI may help when radiographs do not show the suspected injury.`]},clinical:{body:`Relate the navicular to the talar head and cuneiforms while distinguishing overuse injury from a single traumatic event.`,bullets:[`The model does not diagnose a stress injury, test bone strength or set a return-to-running timetable.`]},references:[`https://www.footcaremd.org/foot-and-ankle-conditions/midfoot/navicular-stress-fractures`]},{key:`cuboid`,identities:[[`FMA24529`,`left`,`isa`,[`FJ3258`],`foot`,[`foot`]],[`FMA24528`,`right`,`isa`,[`FJ3364`],`foot`,[`foot`]]],scope:`The cuboid remains one lateral-midfoot bone. No shortening, articular depression or operative distraction is represented.`,pathology:{body:`Cuboid injury can affect the length and joint relationships of the lateral foot column. This is different from simply identifying a loose bone fragment.`,bullets:[`Patient joint surfaces and soft tissues matter as well as bony length.`]},clinical:{body:`Study the cuboid between the calcaneus and lateral metatarsal bases rather than assessing it only in isolation.`,bullets:[`Explode displacement is not a correction of column length, a gait simulation or a guide to surgical reconstruction.`]},references:[`https://surgeryreference.aofoundation.org/orthopedic-trauma/adult-trauma/midfoot/basic-technique/plate-fixation-of-multifragmentary-cuboid-fracture`]},{key:`cuneiforms`,identities:[[`FMA24524`,`left`,`isa`,[`FJ3264`],`foot`,[`foot`]],[`FMA24526`,`left`,`isa`,[`FJ3267`],`foot`,[`foot`]],[`FMA24522`,`left`,`isa`,[`FJ3271`],`foot`,[`foot`]],[`FMA24523`,`right`,`isa`,[`FJ3370`],`foot`,[`foot`]],[`FMA24525`,`right`,`isa`,[`FJ3373`],`foot`,[`foot`]],[`FMA24521`,`right`,`isa`,[`FJ3377`],`foot`,[`foot`]]],scope:`Medial, intermediate and lateral cuneiforms remain separately identified. No Lisfranc ligament tear, measured diastasis or weight-bearing instability is simulated.`,pathology:{body:`Lisfranc-region injury can involve ligaments, fractures or dislocations across the midfoot joint complex. Intact-looking bones do not exclude a ligamentous injury.`,bullets:[`A seemingly minor twisting injury is not enough to dismiss persistent midfoot symptoms as a simple sprain.`]},clinical:{body:`Relate the selected cuneiform to the navicular and metatarsal bases, examining the joint assembly rather than a single bone.`,bullets:[`The atlas cannot test arch stability; separation is an illustrative arrangement, not patient diastasis.`]},references:[`https://www.orthoinfo.org/diseases--conditions/lisfranc-midfoot-injury`]},{key:`first-metatarsal`,identities:[[`FMA24508`,`left`,`isa`,[`FJ3241`],`foot`,[`foot`]],[`FMA24507`,`right`,`isa`,[`FJ3351`],`foot`,[`foot`]]],scope:`The first metatarsal head is part of the first MTP joint, not the hallux IP joint. Cartilage loss and sesamoid contact mechanics are unvalidated.`,pathology:{body:`Hallux rigidus concerns painful stiffness and arthritis at the first MTP joint. A dorsal prominence and limited motion are joint findings, not simply an abnormal first-metatarsal outline.`,bullets:[`Radiological appearance, symptoms and examination must be considered together.`]},clinical:{body:`Study the head against the hallux proximal phalanx, keeping the first-ray base and the toe's IP joint distinct.`,bullets:[`This normal mesh cannot measure cartilage, painful dorsiflexion or the need for joint surgery.`]},references:[`https://www.orthoinfo.org/diseases--conditions/stiff-big-toe-hallux-rigidus`]},{key:`second-metatarsal`,identities:[[`FMA24510`,`left`,`isa`,[`FJ3244`],`foot`,[`foot`]],[`FMA24509`,`right`,`isa`,[`FJ3353`],`foot`,[`foot`]]],scope:`The distal metatarsal head and proximal midfoot base are different clinical regions. No head collapse, growth plate or marrow lesion is modelled.`,pathology:{body:`Freiberg disease most commonly affects the second metatarsal head and may flatten its articular surface. Its cause is not established by the shape of a normal reference bone.`,bullets:[`It is not a synonym for every stress fracture or every painful second metatarsal, and is not assumed to occur exclusively at this bone.`]},clinical:{body:`Distinguish a head/joint problem at the ball of the foot from a shaft injury or proximal midfoot injury.`,bullets:[`No diagnosis, disease stage, age cutoff or treatment choice is assigned by selecting this bone.`]},references:[`https://www.royalberkshire.nhs.uk/media/h20pukxs/freibergs-condition_apr25.pdf`]},{key:`third-fourth-metatarsals`,identities:[[`FMA24512`,`left`,`isa`,[`FJ3247`],`foot`,[`foot`]],[`FMA24514`,`left`,`isa`,[`FJ3250`],`foot`,[`foot`]],[`FMA24511`,`right`,`isa`,[`FJ3355`],`foot`,[`foot`]],[`FMA24513`,`right`,`isa`,[`FJ3357`],`foot`,[`foot`]]],scope:`Each metatarsal keeps its exact ray and side. The normal shaft does not display a fatigue crack, marrow oedema or an individual load distribution.`,pathology:{body:`Metatarsal fractures may follow direct trauma or repetitive loading. Early stress injuries can be difficult to identify on plain radiographs.`,bullets:[`An absence of visible fracture on an early X-ray is not proof that persistent load-related pain is harmless.`]},clinical:{body:`Separate head, shaft and base symptoms, and consider the adjacent joints and other metatarsals.`,bullets:[`Spacing between exploded bones is not a stress test or a measure of safe walking, training load or recovery.`]},references:[`https://www.orthoinfo.org/diseases--conditions/toe-and-forefoot-fractures`,`https://www.orthoinfo.org/diseases--conditions/stress-fractures-of-the-foot-and-ankle`]},{key:`fifth-metatarsal`,identities:[[`FMA24516`,`left`,`isa`,[`FJ3253`],`foot`,[`foot`]],[`FMA24515`,`right`,`isa`,[`FJ3359`],`foot`,[`foot`]]],scope:`The tuberosity, base–shaft transition and shaft remain parts of one bone. No fracture-zone boundary or healing status is segmented.`,pathology:{body:`A tuberosity avulsion and a Jones fracture are different proximal fifth-metatarsal injuries. More distal proximal-shaft stress injuries should not all be labelled Jones fractures.`,bullets:[`The base–shaft junction has a different healing-risk profile from a small tuberosity avulsion; no personal nonunion probability is calculated.`]},clinical:{body:`Locate the injury precisely within the fifth metatarsal rather than using 'base fracture' as a complete description.`,bullets:[`This reference cannot classify a patient's fracture, prescribe weight bearing or choose fixation.`]},references:[`https://www.footcaremd.org/foot-and-ankle-treatments/midfoot/fifth-metatarsal-fracture-surgery`]},{key:`hallux-proximal-phalanx`,identities:[[`FMA43253`,`right`,`isa`,[`FJ3310`],`foot`,[`foot`]],[`FMA43254`,`left`,`isa`,[`FJ3329`],`foot`,[`foot`]]],scope:`The hallux has two phalanges and one IP joint; there is no middle phalanx. The plantar complex and individual sesamoids are not validated by this bone.`,pathology:{body:`Turf toe concerns the plantar soft-tissue complex at the first MTP joint after hyperextension. It is not simply a fracture of the hallux proximal phalanx.`,bullets:[`Bone and plantar-plate or collateral-ligament injury can require separate assessment.`]},clinical:{body:`Distinguish the proximal phalanx base at the MTP joint from its head at the IP joint when orienting hallux injury.`,bullets:[`Explode movement does not reproduce the injury or establish ligament stability, a severity grade or readiness to return to sport.`]},references:[`https://www.orthoinfo.org/diseases--conditions/turf-toe`]},{key:`lesser-toe-proximal-phalanges`,identities:[[`FMA32637`,`left`,`isa`,[`FJ3311`],`foot`,[`foot`]],[`FMA32639`,`left`,`isa`,[`FJ3312`],`foot`,[`foot`]],[`FMA32641`,`left`,`isa`,[`FJ3315`],`foot`,[`foot`]],[`FMA32634`,`right`,`isa`,[`FJ3319`],`foot`,[`foot`]],[`FMA32636`,`right`,`isa`,[`FJ3320`],`foot`,[`foot`]],[`FMA32638`,`right`,`isa`,[`FJ3321`],`foot`,[`foot`]],[`FMA32640`,`right`,`isa`,[`FJ3324`],`foot`,[`foot`]],[`FMA32635`,`left`,`isa`,[`FJ3328`],`foot`,[`foot`]]],scope:`These proximal phalanges retain their own digits and sides. No plantar-plate tear, MTP dislocation or crossover-toe mechanics are reconstructed.`,pathology:{body:`Plantar-plate injury can make a lesser MTP joint unstable and allow the toe to drift from its normal position. This is a soft-tissue problem, not necessarily a fractured proximal phalanx.`,bullets:[`Pain or altered toe position alone does not identify the injured tissue.`]},clinical:{body:`Relate the phalanx base to its metatarsal head, keeping the MTP joint distinct from the PIP joint farther along the toe.`,bullets:[`The model does not perform an instability test or prove that a drifting toe has a plantar-plate tear.`]},references:[`https://www.footcaremd.org/foot-and-ankle-conditions/toes/plantar-plate-tear`]},{key:`lesser-toe-middle-phalanges`,identities:[[`FMA32643`,`left`,`isa`,[`FJ3293`],`foot`,[`foot`]],[`FMA32645`,`left`,`isa`,[`FJ3294`],`foot`,[`foot`]],[`FMA32647`,`left`,`isa`,[`FJ3295`],`foot`,[`foot`]],[`FMA230988`,`left`,`isa`,[`FJ3298`],`foot`,[`foot`]],[`FMA32642`,`right`,`isa`,[`FJ3300`],`foot`,[`foot`]],[`FMA32644`,`right`,`isa`,[`FJ3301`],`foot`,[`foot`]],[`FMA32646`,`right`,`isa`,[`FJ3302`],`foot`,[`foot`]],[`FMA230986`,`right`,`isa`,[`FJ3305`],`foot`,[`foot`]]],scope:`The selected middle phalanx lies between PIP and DIP joints. The hallux has no middle phalanx; flexible versus fixed deformity is not simulated.`,pathology:{body:`Hammertoe describes flexion at the PIP joint of a lesser toe. It concerns a joint and soft-tissue balance, not simply an intrinsically bent middle-phalanx bone.`,bullets:[`A bent PIP joint and a distal-joint deformity should not be described as the same anatomical finding.`]},clinical:{body:`Identify the involved joint before relating the toe shape to symptoms or shoe pressure.`,bullets:[`A static source cannot establish whether a deformity is flexible, explain its cause or prescribe a corrective procedure.`]},references:[`https://www.orthoinfo.org/diseases--conditions/hammer-toe`]},{key:`toe-distal-phalanges`,identities:[[`FMA32653`,`left`,`isa`,[`FJ3179`],`foot`,[`foot`]],[`FMA32655`,`left`,`isa`,[`FJ3180`],`foot`,[`foot`]],[`FMA32657`,`left`,`isa`,[`FJ3181`],`foot`,[`foot`]],[`FMA32651`,`left`,`isa`,[`FJ3182`],`foot`,[`foot`]],[`FMA32659`,`left`,`isa`,[`FJ3185`],`foot`,[`foot`]],[`FMA32652`,`right`,`isa`,[`FJ3189`],`foot`,[`foot`]],[`FMA32654`,`right`,`isa`,[`FJ3190`],`foot`,[`foot`]],[`FMA32656`,`right`,`isa`,[`FJ3191`],`foot`,[`foot`]],[`FMA32650`,`right`,`isa`,[`FJ3192`],`foot`,[`foot`]],[`FMA32658`,`right`,`isa`,[`FJ3195`],`foot`,[`foot`]]],scope:`Each terminal phalanx keeps its own toe and side. The hallux IP and lesser-toe DIP joints differ; nail bed, skin wound and circulation are not depicted.`,pathology:{body:`Stubbing or crushing a toe may injure both bone and nearby soft tissues. A normal-looking bony outline does not exclude a fracture or an important wound.`,bullets:[`A suspected big-toe fracture, a markedly deformed toe, exposed bone or numbness needs emergency assessment under NHS guidance; a significant wound also needs urgent care.`]},clinical:{body:`Distinguish the terminal bone from its nail and skin, and do not apply an uncomplicated lesser-toe pathway automatically to the big toe.`,bullets:[`No taping, nail-drainage, wound-treatment or return-to-activity instructions are provided.`]},references:[`https://www.orthoinfo.org/diseases--conditions/toe-and-forefoot-fractures`,`https://www.nhs.uk/conditions/broken-toe/`]}],b=new Map(y.flatMap(e=>e.identities.map(t=>[t[0],{group:e,identity:t}]))),x=(e,t)=>e.length===t.length&&e.every((e,n)=>e===t[n]);function S(e,t){if(t!==`pathology`&&t!==`clinical`||e.system!==`skeleton`||e.category!==`bone`)return;let n=b.get(e.fmaId);if(!n)return;let[,r,i,a,o,s]=n.identity;if(e.laterality!==r||e.sourceTree!==i||e.region!==o||!x(e.regions,s)||!x(e.sources.map(e=>e.file),a))return;let{group:c}=n,l=c[t];return{readiness:`draft`,title:`${e.name} · ${t===`pathology`?`Injury & disease`:`Clinical context`} · draft`,body:l.body,bullets:[...l.bullets,c.scope],note:[`Draft teaching; independent anatomical and clinical review pending. Educational context, not a patient diagnosis or treatment plan.`,e.coverageNote].filter(Boolean).join(` `),citations:[...c.references]}}export{f as a,d as c,v as i,e as l,S as n,m as o,h as r,l as s,y as t,n as u};